{"formatVersion":3,"title":"Inches to Centimetres","description":"Convert inches to centimetres with a one-inch stepper or a typed value.","capabilities":[],"capabilityResults":false,"stateSchema":{"inches":"number","cm":"number","mm":"number"},"initialState":{"inches":0,"cm":0,"mm":0},"ui":{"type":"column","children":[{"type":"metric","text":"Centimetres","bind":"cm","format":"number","style":{"emphasis":"number"}},{"type":"text","text":"Millimetres","bind":"mm","format":"number","style":{"tone":"muted"}},{"type":"row","style":{"gap":"small"},"children":[{"type":"button","text":"-1 in","action":"dec","variant":"outlined"},{"type":"numberInput","text":"Inches","bind":"inches","action":"setInches","min":0,"max":1000000,"layout":{"weight":2}},{"type":"button","text":"+1 in","action":"inc","variant":"filled"}]},{"type":"text","text":"Step by whole inches, or type a value and tap Apply.","style":{"tone":"muted"}}]},"behaviorBindings":{"inc":"inc","dec":"dec","cm":[0],"inches":[2,1]},"source":"const event = input.event;
const MAX = 1000000;

function round2(n) {
  return Math.round(n * 100) / 100;
}

function derive(inches) {
  return { cm: round2(inches * 2.54), mm: round2(inches * 25.4) };
}

let state = input.state;

if (event && event.type === 'action') {
  let inches = Number(state.inches);
  if (!isFinite(inches)) {
    inches = 0;
  }

