  }

  if (!isFinite(inches)) {
    inches = Number(state.inches);
  }
  if (inches > MAX) {
    inches = MAX;
  }
  if (inches < 0) {
    inches = 0;
  }
  inches = round2(inches);

  const result = derive(inches);
  state = Object.assign({}, state, {
