{"formatVersion":3,"title":"Wallpaper roll calculator","description":"Work out how many 5.3 m² wallpaper rolls you need for a wall area, with an optional extra allowance and the area left spare.","capabilities":[],"capabilityResults":false,"stateSchema":{"area":"number","allowance":"number","effArea":"number","rolls":"number","covered":"number","spare":"number","showHint":"boolean"},"initialState":{"area":0,"allowance":0,"effArea":0,"rolls":0,"covered":0,"spare":0,"showHint":true},"ui":{"type":"column","children":[{"type":"form","text":"Wallpaper quantities","children":[{"type":"numberInput","text":"Wall area (m²)","bind":"area","action":"applyArea","min":0,"max":1000000},{"type":"numberInput","text":"Extra allowance (%)","bind":"allowance","action":"applyAllowance","min":0,"max":1000}]},{"type":"card","text":"Result","children":[{"type":"metric","text":"Rolls needed","bind":"rolls","format":"number","style":{"emphasis":"number"}},{"type":"facts","children":[{"type":"fact","text":"Area incl. allowance (m²)","bind":"effArea"},{"type":"fact","text":"Area covered (m²)","bind":"covered"},{"type":"fact","text":"Spare area (m²)","bind":"spare"}]},{"type":"text","text":"Enter a wall area greater than zero to see the result.","visibleBind":"showHint"}]}]},"behaviorBindings":{"area":"applyArea","rolls":[1,0],"covered":[1,1,1]},"source":"const event = input.event;
