function round2(n) {
  return Math.round(n * 100) / 100;
}
function compute(area, allowance) {
  let a = Number(area);
  let p = Number(allowance);
  if (!isFinite(a) || a < 0) { a = 0; }
  if (!isFinite(p) || p < 0) { p = 0; }
  const hasArea = a > 0;
  if (!hasArea) {
    return { area: a, allowance: p, effArea: 0, rolls: 0, covered: 0, spare: 0, showHint: true };
